BEGIN;
CREATE TABLE knowledge_version_governance(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,source_id uuid NOT NULL,owner_id uuid NOT NULL,submitter_id uuid NOT NULL,classification text NOT NULL,original_checksum text NOT NULL CHECK(original_checksum~'^sha256:[a-f0-9]{64}$'),normalized_checksum text NOT NULL CHECK(normalized_checksum~'^sha256:[a-f0-9]{64}$'),policy_version text NOT NULL,parser_version text NOT NULL,observed_at timestamptz NOT NULL,valid_from timestamptz NOT NULL,valid_until timestamptz,freshness_sla_seconds integer NOT NULL CHECK(freshness_sla_seconds BETWEEN 300 AND 2678400),state text NOT NULL CHECK(state IN('pending_review','approved','effective','conflicted','rejected','superseded','expired','revoked')),governance_version bigint NOT NULL DEFAULT 1 CHECK(governance_version>0),decided_by uuid,decided_at timestamptz,reason_hash text CHECK(reason_hash~'^sha256:[a-f0-9]{64}$'),PRIMARY KEY(tenant_id,workspace_id,asset_id,version_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,version_id)REFERENCES knowledge_asset_version(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,owner_id)REFERENCES iam_user(tenant_id,user_id)ON DELETE RESTRICT,CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE UNIQUE INDEX one_effective_knowledge_version ON knowledge_version_governance(tenant_id,workspace_id,asset_id)WHERE state='effective';
CREATE TABLE knowledge_version_conflict(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,conflict_id uuid NOT NULL,asset_id uuid NOT NULL,existing_version_id uuid NOT NULL,candidate_version_id uuid NOT NULL,state text NOT NULL CHECK(state IN('open','resolved')),resolution text CHECK(resolution IN('keep_existing','publish_candidate','reject_both')),resolved_by uuid,reason_hash text CHECK(reason_hash~'^sha256:[a-f0-9]{64}$'),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL,resolved_at timestamptz,PRIMARY KEY(tenant_id,workspace_id,conflict_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,existing_version_id)REFERENCES knowledge_version_governance(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,workspace_id,asset_id,candidate_version_id)REFERENCES knowledge_version_governance(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,CHECK(existing_version_id<>candidate_version_id));
CREATE TABLE knowledge_governance_outbox(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,event_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('knowledge.version.submitted.v1','knowledge.version.approved.v1','knowledge.version.rejected.v1','knowledge.version.effective.v1','knowledge.version.superseded.v1','knowledge.version.stale.v1','knowledge.version.expired.v1','knowledge.version.revoked.v1','knowledge.version.conflict_opened.v1','knowledge.version.conflict_resolved.v1')),request_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,source_id uuid NOT NULL,state text NOT NULL,governance_version bigint NOT NULL,policy_version text NOT NULL,occurred_at timestamptz NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,workspace_id,event_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,version_id)REFERENCES knowledge_version_governance(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT);
REVOKE ALL ON knowledge_version_governance,knowledge_version_conflict,knowledge_governance_outbox FROM PUBLIC;GRANT SELECT,INSERT,UPDATE(state,governance_version,decided_by,decided_at,reason_hash)ON knowledge_version_governance TO domus_knowledge_runtime;GRANT SELECT,INSERT,UPDATE(state,resolution,resolved_by,reason_hash,version,resolved_at)ON knowledge_version_conflict TO domus_knowledge_runtime;GRANT SELECT,INSERT ON knowledge_governance_outbox TO domus_knowledge_runtime;
ALTER TABLE knowledge_version_governance ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_version_governance FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_version_conflict ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_version_conflict FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_governance_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_governance_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY knowledge_version_governance_scope ON knowledge_version_governance TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_version_conflict_scope ON knowledge_version_conflict TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_governance_outbox_scope ON knowledge_governance_outbox TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description)VALUES(15,'V1-405 knowledge version governance validity and freshness')ON CONFLICT(version)DO NOTHING;COMMIT;
